insert into public.recipes
    (slug, title, emoji, description, total_minutes, difficulty, servings, published,
     source_name, source_url, license_name, attribution, modified_from_source)
values
    ('wikibooks_pan_fried_white_brined_cheese_saganaki', 'Pan-Fried White Brined Cheese (Saganaki)', '🍽️', 'Saganaki is a Greek or Greek-American dish consisting of a hard, white, brined cheese cooked simply with olive oil in a hot pan (traditionally a two-handed vessel whence the name of the dish), usually served with...', 5, 'Easy', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3APan-Fried+White+Brined+Cheese+%28Saganaki%29&oldid=4613881', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_corn_chowder_i', 'Corn Chowder I', '🥔', '| American cuisine | Native American cuisine | Corn | Soups', 60, 'Very easy', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACorn+Chowder+I&oldid=4519255', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_fribourg_omelet', 'Fribourg Omelet', '🍳', '__NOTOC__ A Fribourg omelet is a mix of eggs, crunchy greens, and ham, with the Swiss canton of Fribourg’s native Gruyère cheese adding an acidic punch to bind the flavors together.', 15, 'Medium', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AFribourg+Omelet&oldid=4608896', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_strawberry_frozen_yogurt', 'Strawberry Frozen Yogurt', '🍽️', 'A practical recipe for Strawberry Frozen Yogurt, adapted from the Wikibooks Cookbook.', 45, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AStrawberry+Frozen+Yogurt&oldid=4587425', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_italian_meatballs', 'Italian Meatballs', '🍞', 'A practical recipe for Italian Meatballs, adapted from the Wikibooks Cookbook.', 40, 'Easy', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AItalian+Meatballs&oldid=4514964', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 'Ají de Gallina (Peruvian Chili Chicken)', '🍚', 'The dish is often referred to as ají de pollo when it is prepared with frayed chicken breasts — especially nowadays in which, unlike egg hens raised traditionally on farm lots, the poultry industry breeds caged birds...', 45, 'Easy', 8, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AAj%C3%AD+de+Gallina+%28Peruvian+Chili+Chicken%29&oldid=4603622', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_spinach_mushroom_omelet', 'Spinach Mushroom Omelet', '🍳', 'This spinach mushroom omelet is an American diner-style breakfast dish that provides a creamy mix of fresh vegetable taste and sharp cheddar.', 20, 'Medium', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASpinach+Mushroom+Omelet&oldid=4606145', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_agnolotti_pasta_soup_agnolotti_in_brodo', 'Agnolotti Pasta Soup (Agnolotti in Brodo)', '🥣', 'Agnolotti in brodo is a very simple and delicious Italian pasta soup containing agnolotti, small ravioli filled most commonly with meat. This soup is delicious on a cold day when you haven''t much time to devote to...', 15, 'Easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AAgnolotti+Pasta+Soup+%28Agnolotti+in+Brodo%29&oldid=4525803', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_baked_potato_halves', 'Baked Potato Halves', '🥔', '| Side dishes Baked potato halves is a simple potato dish made without peeling the potatoes.', 60, 'Easy', 2, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ABaked+Potato+Halves&oldid=4503137', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_three_sisters_soup', 'Three Sisters Soup', '🥣', 'Three sisters soup is a classic Indigenous recipe steeped in the folklore of the three staples of Indigenous cultures in North America: corn, squash, and beans. This hearty and delicious soup pays homage to the rich...', 45, 'Easy', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AThree+Sisters+Soup&oldid=4535148', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_jambons', 'Jambons', '🍳', 'Jambons are a type of square pastry filled with cheese and ham. The name is derived from the French word for ham, and they are common in Ireland and the UK.', 30, 'Medium', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AJambons&oldid=4587200', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_fried_bananas', 'Fried Bananas', '🍽️', 'Fried bananas is a delightful dessert or snack enjoyed in many cuisines around the world. These sweet, caramelized banana slices offer a perfect balance of crispy and tender textures. Whether served on their own or...', 20, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AFried+Bananas&oldid=4587508', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_swedish_meatballs_i', 'Swedish Meatballs I', '🍞', '| Meat Recipes | Cuisine of Sweden', 30, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASwedish+Meatballs+I&oldid=4523303', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 'Kasnocken (Austrian Cheese Dumplings)', '🍳', 'Kasnocken are usually served with lettuce and a glass of milk. Since this fare is rather hard to digest, especially for people not used to such opulent meals, the meal may be rounded off with a schnaps.', 25, 'Easy', 3, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AKasnocken+%28Austrian+Cheese+Dumplings%29&oldid=4511373', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true)
on conflict (slug) do update set
