insert into public.recipe_steps (recipe_id, step_number, instruction)
select r.id, v.step_number, v.instruction
from (values
    ('wikibooks_pan_fried_white_brined_cheese_saganaki', 1, 'Heat a small frying pan over medium-high heat.'),
    ('wikibooks_pan_fried_white_brined_cheese_saganaki', 2, 'While the pan heats, cut the cheese into slices of the desired size and thickness. Thicker slices will take longer to melt through and may result in burning, while thinner ones will have less chance to brown.'),
    ('wikibooks_pan_fried_white_brined_cheese_saganaki', 3, 'Optionally, dredge the slices in flour—this will create a darker and slightly crispier crust, but is an optional step as the cheese will acquire a very slight crust on its own by virtue of the oil and high heat. It will also reduce the spitting somewhat.'),
    ('wikibooks_pan_fried_white_brined_cheese_saganaki', 4, 'Add the oil to the hot pan and swirl it around. When the oil shimmers and seems to become more fluid, it is ready. Add the cheese and step back—it will spit due to the brine-water on the cheese.'),
    ('wikibooks_pan_fried_white_brined_cheese_saganaki', 5, 'Flip the cheese after a minute or two. A slice of ¾ centimeter should get about 1–2 minutes per side.'),
    ('wikibooks_pan_fried_white_brined_cheese_saganaki', 6, 'Serve immediately, with lemon and (optionally) bread.'),
    ('wikibooks_corn_chowder_i', 1, 'In a medium saucepan, melt butter; add onion and celery and cook until tender.'),
    ('wikibooks_corn_chowder_i', 2, 'Add potatoes, corn, salt, pepper, water, bouillon cubes, and thyme.'),
    ('wikibooks_corn_chowder_i', 3, 'Cover and simmer for 15 minutes, or until potatoes and corn are tender.'),
    ('wikibooks_corn_chowder_i', 4, 'Add milk and cream.'),
    ('wikibooks_corn_chowder_i', 5, 'Heat through.'),
    ('wikibooks_fribourg_omelet', 1, 'In a large bowl, whisk together the eggs, salt, pepper, milk and nutmeg, until even and glossy.'),
    ('wikibooks_fribourg_omelet', 2, 'Place half the butter in the skillet on medium heat. Swirl the pan to coat evenly with butter.'),
    ('wikibooks_fribourg_omelet', 3, 'Add ham and cook until deep brown.'),
    ('wikibooks_fribourg_omelet', 4, 'Stir in kale for 30 seconds, or until slightly wilted but still crunchy. Set aside the ham and greens.'),
    ('wikibooks_fribourg_omelet', 5, 'Add the remainder of the butter to the skillet over low heat.'),
    ('wikibooks_fribourg_omelet', 6, 'Pour egg mixture into the skillet, moving skillet to create a flat, even layer. Heat until the eggs have begun to set, with some fluff on top.'),
    ('wikibooks_fribourg_omelet', 7, 'Scatter the ham and kale evenly over the top of the eggs.'),
    ('wikibooks_fribourg_omelet', 8, 'Lay the Gruyère slices over the open omelet. Heat until the edges of the cheese have melted slightly.'),
    ('wikibooks_fribourg_omelet', 9, 'Gently push the edges of the omelet less than half a centimeter toward the center of the skillet with two spatulas, making sure not to break it. Turn the heat off.'),
    ('wikibooks_fribourg_omelet', 10, 'Use the spatulas to lift half the omelet and fold over the other half. Move the entire omelet carefully onto a plate and serve.'),
    ('wikibooks_strawberry_frozen_yogurt', 1, 'Wash and dry the strawberries and lemon.'),
    ('wikibooks_strawberry_frozen_yogurt', 2, 'Slice strawberries into small pieces.'),
    ('wikibooks_strawberry_frozen_yogurt', 3, 'Combine strawberries and sugar.'),
    ('wikibooks_strawberry_frozen_yogurt', 4, 'Roll a lemon on a counter while applying pressure with the palm of one hand. Cut lemon in half and squeeze both halves through a strainer into the strawberry mixture.'),
    ('wikibooks_strawberry_frozen_yogurt', 5, 'Remove any remaining seeds from the lemon halves and add them, with the rind, to the strawberry mixture.'),
    ('wikibooks_strawberry_frozen_yogurt', 6, 'Allow strawberry mixture to macerate for 1–2 hours, stirring occasionally until all of the sugar crystals are dissolved.'),
    ('wikibooks_strawberry_frozen_yogurt', 7, 'Discard lemon halves, then orange liqueur to the strawberry mixture.'),
    ('wikibooks_strawberry_frozen_yogurt', 8, 'Use a blender or food processor to reduce the strawberry mixture to a purée, but don''t over-blend.'),
    ('wikibooks_strawberry_frozen_yogurt', 9, 'Stir the Greek yogurt into to the strawberry mixture, mixing until well combined.'),
    ('wikibooks_strawberry_frozen_yogurt', 10, 'Refrigerate strawberry yogurt mixture for at 4 four hours.'),
    ('wikibooks_strawberry_frozen_yogurt', 11, 'Pour strawberry yogurt mixture into a prepared ice cream maker, and mix for approximately 20 minutes, or until the frozen yogurt has reached a firm consistency.'),
    ('wikibooks_strawberry_frozen_yogurt', 12, 'Eat immediately, or freeze for later.'),
    ('wikibooks_italian_meatballs', 1, 'Mix all ingredients together in a large bowl. Using your hands, squeeze all ingredients.'),
    ('wikibooks_italian_meatballs', 2, 'Heat a large skillet over medium heat and drizzle on a little olive oil. Preheat oven to 175°C (350°F) in the meantime.'),
    ('wikibooks_italian_meatballs', 3, 'Use your hands to roll meat into bite sized balls.'),
    ('wikibooks_italian_meatballs', 4, 'Place the meatballs in the skillet and cook uncovered for 3 minutes, then roll them over and cook another 3 minutes.'),
    ('wikibooks_italian_meatballs', 5, 'Transfer the meatballs onto a baking sheet and bake in the oven for 20–25 minutes.'),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 1, 'Boil chicken in salted water together with the stock cube. Remove bones and break into bite size pieces, keeping the resulting chicken stock.'),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 2, 'In a saucepan, heat oil and sauté the onion, garlic, and finely chopped chili peppers and add salt and pepper. Fry this until the onions are cooked and golden.'),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 3, 'Soak the bread in two cups of the stock from the boiled chicken and place in a blender for a couple of minutes and then add the resulting liquid to the saucepan.'),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 4, 'Cook slowly for ten minutes. Cook slowly, stirring to thicken.'),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 5, 'While the Ají de Gallina is cooking slowly, boil the rice: first fry the garlic for a couple of seconds, then add the rice and the salt, then add the water. When the water starts to boil, let the rice cook in a closed pot very slowly for about 20 minutes or until the water has completely evaporated (hint: to cook "peruvian" rice: cook a cup of rice in two cups of water).'),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 6, 'Back to the Ají de Gallina: add the chopped pecans, grated cheese, and chicken pieces. Cook until it has a thick creamy texture. About five minutes before serving, add the evaporated milk and continue cooking on low heat.'),
    ('wikibooks_aji_de_gallina_peruvian_chili_chicken', 7, 'Serve over the boiled rice and garnish with halved potatoes, eggs quartered lengthwise, and olives.'),
    ('wikibooks_spinach_mushroom_omelet', 1, 'In a large bowl, whisk the eggs, salt, pepper, nutmeg and milk, until even and glossy.'),
    ('wikibooks_spinach_mushroom_omelet', 2, 'Heat the skillet over medium heat. Add half the butter, tilting the skillet in a circular motion to coat evenly.'),
    ('wikibooks_spinach_mushroom_omelet', 3, 'Add paprika, mushrooms, and onions, and sauté until lightly browned.'),
    ('wikibooks_spinach_mushroom_omelet', 4, 'Add spinach and toss for 30 seconds, or until slightly wilted, but still crunchy. Remove the vegetables from the heat and set aside.'),
    ('wikibooks_spinach_mushroom_omelet', 5, 'Add the remaining half of the oil or butter to the pan over medium heat, and coat evenly. Lower the heat.'),
    ('wikibooks_spinach_mushroom_omelet', 6, 'Pour the egg mixture into the skillet, swirling the pan to ensure an even, creamy layer of eggs. Heat until the eggs have begun to set, with some fluff on top.'),
    ('wikibooks_spinach_mushroom_omelet', 7, 'Top the egg layer with the vegetables, distributing the vegetables evenly. Sprinkle the cheese evenly on top.'),
    ('wikibooks_spinach_mushroom_omelet', 8, 'Gently push the edges of the omelet half a centimeter toward the center of the skillet with two spatulas, making sure not to break it. Turn the heat off.'),
    ('wikibooks_spinach_mushroom_omelet', 9, 'Use the spatulas to carefully lift/pull half the omelet off the skillet and fold it over the other half. Carefully move the entire omelet onto a plate and serve.'),
    ('wikibooks_agnolotti_pasta_soup_agnolotti_in_brodo', 1, 'Bring the chicken broth to a rolling boil. If using water and chicken stock cubes, bring the water to a boil, add the stock cubes and let dissolve.'),
    ('wikibooks_agnolotti_pasta_soup_agnolotti_in_brodo', 2, 'Add the agnolotti and cook according to the instructions on the package.'),
    ('wikibooks_agnolotti_pasta_soup_agnolotti_in_brodo', 3, 'Add the cream, freshly-ground black pepper, and chopped parsley about 2 minutes before the end of the cooking, and turn down the heat.'),
    ('wikibooks_agnolotti_pasta_soup_agnolotti_in_brodo', 4, 'Add the dash of sherry just before serving. If serving to children, dish out their portions first, then add the sherry for the grown-ups.'),
    ('wikibooks_agnolotti_pasta_soup_agnolotti_in_brodo', 5, 'Let stand for a few minutes to marry the flavors, then serve, sprinkled with grated Parmesan cheese and enjoy.'),
    ('wikibooks_baked_potato_halves', 1, 'Select potatoes of similar size—around 250 grams each.'),
    ('wikibooks_baked_potato_halves', 2, 'Wash potatoes well and cut out any bad parts. Do not peel.'),
    ('wikibooks_baked_potato_halves', 3, 'Cut every potato in two halves, in the direction that will produce the thinnest halves.'),
    ('wikibooks_baked_potato_halves', 4, 'Put ¼ to ½ tsp of salt onto the flat side of one half, and rub both halves together, so that they are both salted.'),
    ('wikibooks_baked_potato_halves', 5, 'Place the potatoes onto a greased pan, flat side down, and into the oven preheated to 220°C. The potatoes should be baked after 45 minutes. The flat sides should form a tasty orange crust.'),
    ('wikibooks_baked_potato_halves', 6, 'Serve hot. The potatoes can be peeled by hand while eating or eaten unpeeled.'),
    ('wikibooks_three_sisters_soup', 1, 'In a large pot, combine the hominy, green beans, squash, and potatoes.'),
    ('wikibooks_three_sisters_soup', 2, 'Add water and chicken bouillon.'),
    ('wikibooks_three_sisters_soup', 3, 'Bring to a boil, then reduce heat to low and simmer until the vegetables are soft (approximately 10 minutes).'),
    ('wikibooks_three_sisters_soup', 4, 'In a separate pan, melt the butter and whisk in the flour. Stir the mixture into the soup.'),
    ('wikibooks_three_sisters_soup', 5, 'Increase heat to medium and cook until the soup thickens (approximately 5 minutes).'),
    ('wikibooks_three_sisters_soup', 6, 'Season with salt and pepper to taste.'),
    ('wikibooks_three_sisters_soup', 7, 'Serve your delicious three sisters soup. Garnish with fresh herbs or Indigenous spices for added flavor.'),
    ('wikibooks_jambons', 1, 'Preheat oven to 200°C (400°F).'),
    ('wikibooks_jambons', 2, 'Melt butter over medium heat and add flour. Cook for 5 minutes and begin adding milk gradually until the mixture thickens.'),
    ('wikibooks_jambons', 3, 'Cut your pre-prepared puff pastry into squares and spoon a generous amount of the mixture onto each square. Sprinkle some ham and grated cheese on top.'),
    ('wikibooks_jambons', 4, 'Fold the corners of the puff pastry so that they meet in the centre, forming a panier feuilleté (puff pastry basket) shape.'),
    ('wikibooks_jambons', 5, 'Beat the egg and brush it over each sealed panier feuilleté.'),
    ('wikibooks_jambons', 6, 'Bake for 20–25 minutes until puffed and golden brown.'),
    ('wikibooks_fried_bananas', 1, 'Heat a skillet or frying pan over medium heat and melt the butter.'),
    ('wikibooks_fried_bananas', 2, 'Add the banana slices to the pan and sprinkle them with brown sugar.'),
    ('wikibooks_fried_bananas', 3, 'Cook the bananas for 2–3 minutes on each side or until they turn golden brown and caramelized.'),
    ('wikibooks_fried_bananas', 4, 'If desired, sprinkle cinnamon over the bananas during cooking.'),
    ('wikibooks_fried_bananas', 5, 'Remove the fried bananas from the pan and serve them hot. Optionally, serve with a scoop of vanilla ice cream for an extra treat.'),
    ('wikibooks_swedish_meatballs_i', 1, 'Combine the liquid and bread crumbs in a bowl, and let it sit for 7–8 minutes.'),
    ('wikibooks_swedish_meatballs_i', 2, 'Mix in the ground beef, ground pork, egg, onion, salt, and pepper.'),
    ('wikibooks_swedish_meatballs_i', 3, 'Shape the mixture into round meatballs, approximately 2–3 centimeters (1 inch) in diameter.'),
    ('wikibooks_swedish_meatballs_i', 4, 'Pan fry the meatballs on medium heat in a frying pan with butter for approximately 3–5 minutes. Fry them on all sides until they are brown and not pink in the middle. Shaking the pan occasionally will help the meatballs cook evenly.'),
    ('wikibooks_swedish_meatballs_i', 5, 'Serve them with mashed potatoes with a veal based brown sauce made with cream and lingonberry preserve or cranberry preserve.'),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 1, 'Mix flour, eggs, water, and salt carefully to get a dough; it should neither be stiff nor too soft.'),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 2, 'Pass the dough through a special press for dumplings into boiling, salted water.'),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 3, 'Boil the small dumplings for about 3 minutes, then drain and rinse them with cold water.'),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 4, 'Melt the butter in a pan, add the dumplings, and season them with salt and pepper.'),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 5, 'Gradually add the grated cheese and stir vigorously.'),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 6, 'When all of the cheese has melted, heat butter in another pan, add the onion rings, and fry them until they become golden brown.'),
    ('wikibooks_kasnocken_austrian_cheese_dumplings', 7, 'Top the dumplings with the onion rings and chives.')
) as v(recipe_slug, step_number, instruction)
join public.recipes r on r.slug = v.recipe_slug;

